import {yin} from './music.js';
let history=[],smooth=0;
onmessage=({data})=>{if(data.type==='pitch'){const r=yin(data.samples,data.rate);if(r.frequency){const f=Math.log(r.frequency);if(smooth&&Math.abs(f-smooth)>.08){history=[];smooth=0;}history.push(f);if(history.length>3)history.shift();const med=[...history].sort((a,b)=>a-b)[Math.floor(history.length/2)];smooth=smooth?smooth+.55*(med-smooth):med;r.frequency=history.length<2?0:Math.exp(smooth);}else{history=[];smooth=0;}postMessage(r);}else if(data.type==='tempo'){const a=data.samples,rate=data.rate,step=Math.floor(rate*.01),env=[];for(let i=0;i<a.length;i+=step){let e=0;for(let j=i;j<Math.min(i+step,a.length);j++)e+=a[j]*a[j];env.push(Math.sqrt(e/step));}const onset=env.map((v,i)=>Math.max(0,v-(env[i-1]||0))),energy=onset.reduce((s,v)=>s+v*v,0);let best=0,score=0;for(let lag=33;lag<=150;lag++){let x=0;for(let i=lag;i<onset.length;i++)x+=onset[i]*onset[i-lag];if(x>score){score=x;best=lag;}}postMessage({bpm:score>energy*.15?Math.round(6000/best):0});}};
